import numpy as np
from scipy.optimize import least_squares
S=df.S.values; I=df.I.values; v=df.v.values
def mk(kind):
    def f(p,S,I):
        Vm=np.exp(p[0]); Km=np.exp(p[1]); Ki=np.exp(p[2])
        if kind=='comp': return Vm*S/(Km*(1+I/Ki)+S)
        if kind=='nonc': return Vm*S/((Km+S)*(1+I/Ki))
        if kind=='unc': return Vm*S/(Km+S*(1+I/Ki))
        if kind=='mixed':
            Ki2=np.exp(p[3]); return Vm*S/(Km*(1+I/Ki)+S*(1+I/Ki2))
        if kind=='mm': return Vm*S/(Km+S)
    return f
res={}
for k in ['mm','comp','nonc','unc','mixed']:
    f=mk(k); best=None
    for a in np.log([5,10,20]):
        for b in np.log([0.5,2,8]):
            for c in np.log([0.3,1,5]):
                p0=[a,b,c,c][:4 if k=='mixed' else 3]
                if k=='mm': p0=[a,b]
                try:
                    r=least_squares(lambda p:f(p,S,I)-v if k!='mm' else mk('mm')(p,S,I)-v, p0)
                except Exception: continue
                if best is None or r.cost<best.cost: best=r
    n=len(v); rss=2*best.cost; kp=len(best.x)
    aic=n*np.log(rss/n)+2*kp; bic=n*np.log(rss/n)+kp*np.log(n)
    res[k]=best
    print(k, np.round(np.exp(best.x),4), 'RSS',round(rss,4),'BIC',round(bic,2))

