    Vm=np.exp(p[0]); Km=np.exp(p[1])
    if kind=='mm': return Vm*S/(Km+S)
    Ki=np.exp(p[2])
    if kind=='comp': return Vm*S/(Km*(1+I/Ki)+S)
    if kind=='nonc': return Vm*S/((Km+S)*(1+I/Ki))
    if kind=='unc': return Vm*S/(Km+S*(1+I/Ki))
    if kind=='mixed':
        Ki2=np.exp(p[3]); return Vm*S/(Km*(1+I/Ki)+S*(1+I/Ki2))
n=len(v)
for k in ['mm','comp','nonc','unc','mixed']:
    best=None
    for a in np.log([5,10,20]):
        for b in np.log([0.5,2,8]):
            for c in np.log([0.3,1,5]):
                p0=[a,b] if k=='mm' else ([a,b,c,c] if k=='mixed' else [a,b,c])
                r=least_squares(lambda p:f(k,p)-v, p0)
